// StartProject.js
import React, { useState } from 'react';
import './StartProject.css'; 

const StartProject = () => {
  const [projectName, setProjectName] = useState('');
  const [projectDescription, setProjectDescription] = useState('');
  const [errors, setErrors] = useState({});

  const validate = () => {
    const newErrors = {};
    if (!projectName.trim()) newErrors.projectName = 'Project name is required.';
    if (!projectDescription.trim()) newErrors.projectDescription = 'Project description is required.';
    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const validationErrors = validate();
    if (Object.keys(validationErrors).length === 0) {
      alert(`🎉 Project "${projectName}" created successfully!`);
      setProjectName('');
      setProjectDescription('');
      setErrors({});
    } else {
      setErrors(validationErrors);
    }
  };

  return (
    <section className="start-project-section">
      <div className="form-container">
        <h2>🚀 Launch Your Open Source Project</h2>
        <p className="subtitle">Kickstart your idea and invite collaborators!</p>
        <form onSubmit={handleSubmit} className="project-form">
          <label htmlFor="projectName">Project Name</label>
          <input
            id="projectName"
            type="text"
            value={projectName}
            onChange={(e) => setProjectName(e.target.value)}
            placeholder="e.g., CodeConnect"
          />
          {errors.projectName && <span className="error">{errors.projectName}</span>}

          <label htmlFor="projectDescription">Project Description</label>
          <textarea
            id="projectDescription"
            value={projectDescription}
            onChange={(e) => setProjectDescription(e.target.value)}
            placeholder="Describe your project's goals and features..."
          />
          {errors.projectDescription && <span className="error">{errors.projectDescription}</span>}

          <button type="submit" className="submit-button">Create Project</button>
        </form>
      </div>
    </section>
  );
};

export default StartProject;
